mapper.select:
SELECT account_id, skill_id, level, definition_version, updated_at
FROM pet_training_skills
WHERE account_id = #{accountId}
  AND skill_id = #{skillId}

mapper.insert:
INSERT INTO pet_training_skills (
    account_id, skill_id, level, definition_version, updated_at
) VALUES (
    #{accountId}, #{skillId}, #{level}, #{definitionVersion}, #{updatedAt}
)

mapper.update:
UPDATE pet_training_skills
SET level = #{level},
    definition_version = #{definitionVersion},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND skill_id = #{skillId}

mapper.select:
SELECT account_id, first_explore_free_available, first_explore_free_used, updated_at
FROM pet_training_flags
WHERE account_id = #{accountId}

mapper.insert:
INSERT OR IGNORE INTO pet_training_flags (
    account_id, first_explore_free_available, first_explore_free_used, updated_at
) VALUES (
    #{accountId}, 0, 0, #{updatedAt}
)

mapper.update:
UPDATE pet_training_flags
SET first_explore_free_available = 1,
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND first_explore_free_available = 0
  AND first_explore_free_used = 0
